insert into public.petitions(id,owner_id,community_id,content,status,sample_count,sample_saves,sample_velocity,created_at) values('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','{"title":"A brighter walk home starts here","summary":"A practical change for a more welcoming neighborhood. Help us install pedestrian lighting along the Eastbridge campus path.","problem":"The path between Eastbridge campus and the bus stop has long gaps between lights. Students describe feeling uncomfortable walking home after evening activities. This fictional petition asks for a lighting assessment and a public implementation plan.","action":"Install pedestrian lighting along the Eastbridge campus path","recipient":"Riverton Public Works (fictional)","topic":"Safer streets","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000001","goal":1000,"deadline":"2027-06-30","evidence":[{"label":"Sample student path audit — illustrative evidence","url":"https://example.org/student-path-audit"}],"verification":"email","identities":["full_name","first_name_last_initial","anonymous"],"customRule":""}'::jsonb,'active',684,28,42,'2026-09-09T23:20:17.862Z') on conflict(id) do nothing;
insert into public.petition_sources(petition_id,label,url) select '20000000-0000-4000-8000-000000000001','Sample student path audit — illustrative evidence','https://example.org/student-path-audit' where not exists(select 1 from public.petition_sources where petition_id='20000000-0000-4000-8000-000000000001' and url='https://example.org/student-path-audit');
insert into public.petition_updates(petition_id,author_id,body) select '20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','We reached our halfway milestone. Next: share the student path audit at the community listening session. All events in this demo are fictional.' where not exists(select 1 from public.petition_updates where petition_id='20000000-0000-4000-8000-000000000001');
insert into public.petition_edits(petition_id,author_id,body,previous_content) select '20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','Clarified the requested action: lighting assessment and a public implementation plan. No eligibility rules changed.','{"title":"A brighter walk home starts here","summary":"A practical change for a more welcoming neighborhood. Help us install pedestrian lighting along the Eastbridge campus path.","problem":"The path between Eastbridge campus and the bus stop has long gaps between lights. Students describe feeling uncomfortable walking home after evening activities. This fictional petition asks for a lighting assessment and a public implementation plan.","action":"Install pedestrian lighting along the Eastbridge campus path","recipient":"Riverton Public Works (fictional)","topic":"Safer streets","city":"Riverton, CA","communityId":"10000000-0000-4000-8000-000000000001","goal":1000,"deadline":"2027-06-30","evidence":[{"label":"Sample student path audit — illustrative evidence","url":"https://example.org/student-path-audit"}],"verification":"email","identities":["full_name","first_name_last_initial","anonymous"],"customRule":""}'::jsonb where not exists(select 1 from public.petition_edits where petition_id='20000000-0000-4000-8000-000000000001');
insert into public.petition_endorsements(petition_id,community_id,body) values('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Riverton students supports this proposal. Sample community endorsement.') on conflict do nothing;
insert into public.discussion_posts(petition_id,author_id,kind,body) select '20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','question','Could the assessment also consider the stretch beside the bus shelter?' where not exists(select 1 from public.discussion_posts where petition_id='20000000-0000-4000-8000-000000000001');
insert into public.official_responses(petition_id,author_id,body,organization,verification) select '20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','We will include the campus path in our next lighting review and invite student input. This is a fictional response for demonstration only.','Riverton Public Works (fictional)','verified' where not exists(select 1 from public.official_responses where petition_id='20000000-0000-4000-8000-000000000001');
